import { useState, useRef, useCallback, useEffect } from 'react';

const API_BASE = 'http://localhost:5001';

// ─── Field metadata ────────────────────────────────────────────────────────────
const FIELD_META = {
  shoot_height_cm:        { label: 'Shoot Height',        unit: 'cm', icon: 'height'   },
  trunk_circumference_cm: { label: 'Trunk Circumference', unit: 'cm', icon: 'trunk'    },
  shoot_age_months:       { label: 'Shoot Age',           unit: 'mo', icon: 'calendar' },
  num_leaves:             { label: 'Leaf Count',          unit: '',   icon: 'leaf'      },
  ccgi_score:             { label: 'CCGI Score',          unit: '',   icon: 'star'      },
  leaf_color:             { label: 'Leaf Colour',         unit: '',   icon: 'palette'   },
  bark_texture:           { label: 'Bark Texture',        unit: '',   icon: 'texture'   },
  bark_color:             { label: 'Bark Colour',         unit: '',   icon: 'palette'   },
  straightness:           { label: 'Straightness',        unit: '',   icon: 'straight'  },
};

const MISSING_FIELD_TIPS = {
  "Shoot height (cm)":          "e.g. 'height 145 cm'",
  "Trunk circumference (cm)":   "e.g. 'trunk 4 cm'",
  "Shoot age (months)":         "e.g. 'age 18 months'",
  "Number of leaves":           "e.g. '16 leaves'",
  "CCGI score":                 "e.g. 'ccgi score 4.5'",
  "Leaf colour":                "e.g. 'yellowish green leaves'",
  "Bark colour":                "e.g. 'dark brown bark'",
  "Bark texture":               "e.g. 'rough and peeling'",
  "Shoot straightness":         "e.g. 'very straight'",
};

// ─── Verdict config ────────────────────────────────────────────────────────────
const VERDICT = {
  'Ready': {
    label:     'Ready for Harvest',
    sub:       'Coppice at 6 cm from ground at a 45° angle for best yield.',
    icon:      'check',
    accent:    '#4ade80',
    glow:      '#22c55e',
    bg:        'rgba(34,197,94,0.07)',
    border:    'rgba(74,222,128,0.25)',
  },
  'Nearly Ready': {
    label:     'Nearly Ready',
    sub:       'Re-assess in 2–4 weeks. Key indicators are improving.',
    icon:      'clock',
    accent:    '#fbbf24',
    glow:      '#f59e0b',
    bg:        'rgba(251,191,36,0.07)',
    border:    'rgba(251,191,36,0.25)',
  },
  'Not Ready': {
    label:     'Not Ready Yet',
    sub:       'The shoot needs more time to develop. Check again in a month.',
    icon:      'x',
    accent:    '#60a5fa',
    glow:      '#3b82f6',
    bg:        'rgba(96,165,250,0.07)',
    border:    'rgba(96,165,250,0.25)',
  },
};

// Confidence tier display config
const TIER_CONFIG = {
  high:     { color: '#4ade80', bg: 'rgba(74,222,128,0.08)',  border: 'rgba(74,222,128,0.2)',  label: 'High Confidence'      },
  medium:   { color: '#fbbf24', bg: 'rgba(251,191,36,0.08)', border: 'rgba(251,191,36,0.2)',  label: 'Medium Confidence'    },
  low:      { color: '#fb923c', bg: 'rgba(251,146,60,0.08)', border: 'rgba(251,146,60,0.2)',  label: 'Low Confidence'       },
  very_low: { color: '#f87171', bg: 'rgba(248,113,113,0.08)',border: 'rgba(248,113,113,0.2)', label: 'Very Low Confidence'  },
};

// ─── Icon system ──────────────────────────────────────────────────────────────
function Icon({ name, size = 18 }) {
  const s = { width: size, height: size, display: 'inline-block', flexShrink: 0 };
  const icons = {
    leaf:     <><path d="M11 20A7 7 0 0 1 9.8 6.1C15.5 5 17 4.48 19 2c1 2 2 4.18 2 8 0 5.5-4.78 10-10 10z"/><path d="M2 21c0-3 1.85-5.36 5.08-6C9.5 14.52 12 13 13 12"/></>,
    height:   <><path d="M8 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h3"/><path d="M16 3h3a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-3"/><path d="M12 8v8M9 11l3-3 3 3"/></>,
    trunk:    <><circle cx="12" cy="12" r="4"/><circle cx="12" cy="12" r="9"/></>,
    calendar: <><rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/></>,
    palette:  <><circle cx="13.5" cy="6.5" r=".5" fill="currentColor"/><circle cx="17.5" cy="10.5" r=".5" fill="currentColor"/><circle cx="8.5" cy="7.5" r=".5" fill="currentColor"/><circle cx="6.5" cy="12.5" r=".5" fill="currentColor"/><path d="M12 2C6.5 2 2 6.5 2 12s4.5 10 10 10c.926 0 1.648-.746 1.648-1.688 0-.437-.18-.835-.437-1.125-.29-.289-.438-.652-.438-1.125a1.64 1.64 0 0 1 1.668-1.668h1.996c3.051 0 5.555-2.503 5.555-5.554C21.965 6.012 17.461 2 12 2z"/></>,
    texture:  <><path d="M4 6h16M4 10h16M4 14h16M4 18h16"/></>,
    straight: <><path d="M12 2v20M2 12h20"/></>,
    star:     <><path d="M11.525 2.295a.53.53 0 0 1 .95 0l2.31 4.679a2.123 2.123 0 0 0 1.595 1.16l5.166.756a.53.53 0 0 1 .294.904l-3.736 3.638a2.123 2.123 0 0 0-.611 1.878l.882 5.14a.53.53 0 0 1-.771.56l-4.618-2.428a2.122 2.122 0 0 0-1.973 0L6.396 21.01a.53.53 0 0 1-.77-.56l.881-5.139a2.122 2.122 0 0 0-.611-1.879L2.16 9.795a.53.53 0 0 1 .294-.906l5.165-.755a2.122 2.122 0 0 0 1.597-1.16z"/></>,
    mic:      <><path d="M12 2a3 3 0 0 1 3 3v7a3 3 0 0 1-6 0V5a3 3 0 0 1 3-3z"/><path d="M19 10v2a7 7 0 0 1-14 0v-2"/><path d="M12 19v3M9 22h6"/></>,
    search:   <><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></>,
    check:    <><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><path d="M22 4 12 14.01l-3-3"/></>,
    clock:    <><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></>,
    x:        <><circle cx="12" cy="12" r="10"/><path d="m15 9-6 6M9 9l6 6"/></>,
    info:     <><circle cx="12" cy="12" r="10"/><path d="M12 16v-4M12 8h.01"/></>,
    chart:    <><path d="M3 3v18h18"/><path d="M18 9l-5 5-4-4-3 3"/></>,
    eye:      <><path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7z"/><circle cx="12" cy="12" r="3"/></>,
    warn:     <><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3z"/><path d="M12 9v4M12 17h.01"/></>,
    sparkle:  <><path d="M9.937 15.5A2 2 0 0 0 8.5 14.063l-6.135-1.582a.5.5 0 0 1 0-.962L8.5 9.936A2 2 0 0 0 9.937 8.5l1.582-6.135a.5.5 0 0 1 .963 0L14.063 8.5A2 2 0 0 0 15.5 9.937l6.135 1.581a.5.5 0 0 1 0 .964L15.5 14.063a2 2 0 0 0-1.437 1.437l-1.582 6.135a.5.5 0 0 1-.963 0z"/></>,
    plus:     <><path d="M5 12h14M12 5v14"/></>,
    shield:   <><path d="M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z"/></>,
  };

  if (name === 'stop') {
    return (
      <svg style={s} viewBox="0 0 24 24" fill="currentColor">
        <rect x="6" y="6" width="12" height="12" rx="2"/>
      </svg>
    );
  }
  return (
    <svg style={s} viewBox="0 0 24 24" fill="none"
      stroke="currentColor" strokeWidth="1.8"
      strokeLinecap="round" strokeLinejoin="round">
      {icons[name] || icons.info}
    </svg>
  );
}

// ─── Global CSS ────────────────────────────────────────────────────────────────
const CSS = `
  @import url('https://fonts.googleapis.com/css2?family=DM+Sans:opsz,wght@9..40,300;9..40,400;9..40,500;9..40,600;9..40,700&family=DM+Serif+Display:ital@0;1&display=swap');

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --bg:        #0a100c;
    --surface:   #101810;
    --surface2:  #141f16;
    --surface3:  #192119;
    --border:    #1c2b1e;
    --border2:   #223026;
    --text:      #e2ebe3;
    --text2:     #a8bfab;
    --muted:     #5c7a62;
    --accent:    #4ade80;
    --accent2:   #22c55e;
    --radius:    14px;
    --ease:      cubic-bezier(0.4,0,0.2,1);
  }

  html { scroll-behavior: smooth; }
  body {
    font-family: 'DM Sans', sans-serif;
    background: var(--bg);
    color: var(--text);
    min-height: 100vh;
    -webkit-font-smoothing: antialiased;
  }
  ::-webkit-scrollbar { width: 4px; }
  ::-webkit-scrollbar-thumb { background: var(--border2); border-radius: 4px; }

  @keyframes fadeUp {
    from { opacity:0; transform:translateY(14px); }
    to   { opacity:1; transform:translateY(0); }
  }
  @keyframes fadeIn  { from{opacity:0} to{opacity:1} }
  @keyframes spin    { to{transform:rotate(360deg)} }
  @keyframes barGrow { from{width:0%} }
  @keyframes glow    { 0%,100%{opacity:.5} 50%{opacity:1} }
  @keyframes recRing {
    0%  {box-shadow:0 0 0 0 rgba(239,68,68,.5)}
    70% {box-shadow:0 0 0 9px rgba(239,68,68,0)}
    100%{box-shadow:0 0 0 0 rgba(239,68,68,0)}
  }
  @keyframes shimmer {
    0%  {background-position:-600px 0}
    100%{background-position:600px 0}
  }
  @keyframes slideDown {
    from{opacity:0;transform:translateY(-6px)}
    to  {opacity:1;transform:translateY(0)}
  }
  @keyframes completePop {
    0%  {transform:scale(1)}
    50% {transform:scale(1.04)}
    100%{transform:scale(1)}
  }

  /* ── Root ── */
  .ch { min-height:100vh; background:var(--bg); }

  /* ── Top bar ── */
  .ch-bar {
    position:sticky; top:0; z-index:100;
    height:54px; padding:0 16px;
    display:flex; align-items:center; gap:10px;
    background:rgba(10,16,12,.88);
    backdrop-filter:blur(18px);
    border-bottom:1px solid var(--border);
  }
  .ch-bar-logo {
    width:28px; height:28px; border-radius:7px; flex-shrink:0;
    background:linear-gradient(135deg,#22c55e,#16a34a);
    display:flex; align-items:center; justify-content:center;
    color:#fff; box-shadow:0 2px 10px #22c55e40;
  }
  .ch-bar-title {
    font-family:'DM Serif Display',serif;
    font-size:.95rem; color:var(--text); flex:1; font-weight:400;
  }
  .ch-bar-pill {
    font-size:.58rem; font-weight:600; letter-spacing:.09em;
    text-transform:uppercase; padding:3px 8px; border-radius:20px;
    background:#22c55e14; color:var(--accent); border:1px solid #22c55e28;
  }

  /* ── Hero ── */
  .ch-hero {
    position:relative; overflow:hidden;
    padding:36px 16px 30px;
    border-bottom:1px solid var(--border);
  }
  .ch-hero::before {
    content:''; position:absolute; inset:0; pointer-events:none;
    background:
      radial-gradient(ellipse 70% 55% at 50% 0%,#22c55e0c 0%,transparent 70%),
      radial-gradient(ellipse 35% 35% at 85% 110%,#4ade8008 0%,transparent 60%);
  }
  .ch-hero-grid {
    position:absolute; inset:0; pointer-events:none; opacity:.035;
    background-image:
      linear-gradient(var(--accent) 1px,transparent 1px),
      linear-gradient(90deg,var(--accent) 1px,transparent 1px);
    background-size:44px 44px;
  }
  .ch-hero-inner {
    position:relative; max-width:580px; margin:0 auto;
    animation:fadeUp .5s var(--ease) both;
  }
  .ch-eyebrow {
    display:inline-flex; align-items:center; gap:7px;
    font-size:.63rem; font-weight:600; letter-spacing:.1em;
    text-transform:uppercase; color:var(--accent); margin-bottom:12px;
  }
  .ch-eyebrow-dot {
    width:5px; height:5px; border-radius:50%;
    background:var(--accent); animation:glow 2s ease infinite;
  }
  .ch-hero-h1 {
    font-family:'DM Serif Display',serif;
    font-size:clamp(1.6rem,5vw,2.15rem);
    line-height:1.15; color:var(--text); font-weight:400; margin-bottom:10px;
  }
  .ch-hero-h1 em { font-style:italic; color:var(--accent); }
  .ch-hero-sub {
    font-size:.81rem; color:var(--muted); line-height:1.65; max-width:400px;
  }

  /* ── Body ── */
  .ch-body {
    max-width:580px; margin:0 auto;
    padding:20px 14px 70px;
    display:flex; flex-direction:column; gap:12px;
  }

  /* ── Card ── */
  .ch-card {
    background:var(--surface); border:1px solid var(--border);
    border-radius:var(--radius); overflow:hidden;
    animation:fadeUp .4s var(--ease) both;
    transition:border-color .2s var(--ease), box-shadow .2s var(--ease);
  }
  .ch-card:focus-within { border-color:var(--border2); box-shadow:0 0 0 3px #22c55e0a; }
  .ch-card-hdr {
    display:flex; align-items:center; gap:10px;
    padding:14px 16px 0;
  }
  .ch-card-ico {
    width:28px; height:28px; border-radius:7px; flex-shrink:0;
    background:var(--surface2); border:1px solid var(--border2);
    display:flex; align-items:center; justify-content:center;
    color:var(--accent);
  }
  .ch-card-lbl {
    font-size:.63rem; font-weight:600; letter-spacing:.09em;
    text-transform:uppercase; color:var(--muted);
  }
  .ch-card-body { padding:12px 16px 16px; }

  /* ── Textarea ── */
  .ch-ta-wrap { position:relative; }
  .ch-ta {
    width:100%; min-height:108px;
    background:var(--surface2); color:var(--text);
    border:1px solid var(--border2); border-radius:10px;
    padding:12px 48px 12px 13px;
    font-family:'DM Sans',sans-serif; font-size:.88rem; line-height:1.68;
    resize:none; outline:none;
    transition:border-color .2s var(--ease), box-shadow .2s var(--ease);
  }
  .ch-ta::placeholder { color:var(--muted); font-size:.8rem; }
  .ch-ta:focus { border-color:#22c55e48; box-shadow:0 0 0 3px #22c55e09; }

  /* ── Mic ── */
  .ch-mic {
    position:absolute; right:9px; bottom:9px;
    width:32px; height:32px; border-radius:50%; border:none; cursor:pointer;
    display:flex; align-items:center; justify-content:center;
    transition:all .2s var(--ease);
  }
  .ch-mic.idle {
    background:var(--surface); border:1px solid var(--border2); color:var(--muted);
  }
  .ch-mic.idle:hover { border-color:var(--accent); color:var(--accent); }
  .ch-mic.rec  { background:#ef4444; color:#fff; border:1px solid #ef4444; animation:recRing 1.4s infinite; }

  /* ── Hint ── */
  .ch-hint {
    display:flex; align-items:center; gap:5px;
    font-size:.65rem; color:var(--muted); margin-top:7px;
  }

  /* ── Analyse button ── */
  .ch-btn {
    width:100%; padding:12px 16px; margin-top:11px;
    border:none; border-radius:10px; cursor:pointer;
    font-family:'DM Sans',sans-serif; font-size:.88rem; font-weight:600;
    display:flex; align-items:center; justify-content:center; gap:8px;
    position:relative; overflow:hidden; transition:all .22s var(--ease);
  }
  .ch-btn.on {
    background:linear-gradient(135deg,#22c55e 0%,#16a34a 100%);
    color:#fff; box-shadow:0 4px 18px #22c55e30;
  }
  .ch-btn.on:hover  { transform:translateY(-1px); box-shadow:0 6px 24px #22c55e42; }
  .ch-btn.on:active { transform:translateY(0); }
  .ch-btn.off {
    background:var(--surface2); color:var(--muted);
    cursor:not-allowed; border:1px solid var(--border2);
  }
  .ch-btn-shimmer {
    position:absolute; inset:0;
    background:linear-gradient(90deg,transparent 0%,rgba(255,255,255,.14) 50%,transparent 100%);
    background-size:600px 100%; animation:shimmer 1.6s infinite;
  }

  /* ── Spinners ── */
  .ch-spin       { width:15px;height:15px;border-radius:50%;border:2px solid rgba(255,255,255,.25);border-top-color:#fff;animation:spin .7s linear infinite; }
  .ch-spin-green { width:15px;height:15px;border-radius:50%;border:2px solid var(--border2);border-top-color:var(--accent);animation:spin .7s linear infinite; }

  /* ── Loading ── */
  .ch-loading {
    display:flex; align-items:center; gap:10px;
    background:var(--surface); border:1px solid var(--border2);
    border-radius:var(--radius); padding:12px 15px;
    font-size:.8rem; color:var(--muted); animation:fadeIn .25s ease;
  }

  /* ── Error ── */
  .ch-err {
    background:#110808; border:1px solid #3a1212;
    border-radius:var(--radius); padding:14px 15px;
    animation:fadeUp .3s ease;
  }
  .ch-err-head { display:flex;align-items:center;gap:7px;font-size:.78rem;font-weight:600;color:#f87171;margin-bottom:5px; }
  .ch-err-body { font-size:.76rem;color:#9a5f5f;line-height:1.55; }
  .ch-err-tip  { font-size:.7rem;color:#6a3f3f;margin-top:5px; }

  /* ── Detected fields grid ── */
  .ch-pills { display:grid; grid-template-columns:repeat(auto-fill,minmax(128px,1fr)); gap:8px; }
  .ch-pill {
    background:var(--surface2); border:1px solid var(--border2);
    border-radius:10px; padding:9px 11px;
    animation:fadeUp .3s ease both; transition:border-color .2s var(--ease);
  }
  .ch-pill:hover { border-color:#22c55e38; }
  .ch-pill-lbl {
    display:flex;align-items:center;gap:5px;
    font-size:.58rem;font-weight:600;letter-spacing:.07em;
    text-transform:uppercase;color:var(--muted);margin-bottom:3px;
  }
  .ch-pill-lbl svg { color:var(--accent); opacity:.8; }
  .ch-pill-val { font-size:.86rem;font-weight:600;color:var(--text); }

  /* ── Completeness bar ── */
  .ch-complete {
    border-radius:var(--radius); padding:14px 15px;
    border:1px solid transparent; animation:fadeUp .35s ease both;
  }
  .ch-complete-top {
    display:flex; align-items:center; justify-content:space-between;
    margin-bottom:10px;
  }
  .ch-complete-left { display:flex;align-items:center;gap:8px; }
  .ch-complete-icon { width:28px;height:28px;border-radius:7px;display:flex;align-items:center;justify-content:center;flex-shrink:0; }
  .ch-complete-tier { font-size:.78rem;font-weight:600; }
  .ch-complete-count { font-size:.7rem;color:var(--muted); }
  .ch-complete-pct { font-size:.75rem;font-weight:700; }
  .ch-progress-track {
    height:5px; background:var(--surface3); border-radius:5px; overflow:hidden; margin-bottom:10px;
  }
  .ch-progress-fill {
    height:100%; border-radius:5px;
    animation:barGrow .8s cubic-bezier(.34,1.56,.64,1) both;
    transition:width .5s var(--ease);
  }

  /* ── Missing fields list ── */
  .ch-missing-head {
    font-size:.63rem;font-weight:600;letter-spacing:.07em;
    text-transform:uppercase;color:var(--muted);margin-bottom:7px;
    display:flex;align-items:center;gap:5px;
  }
  .ch-missing-grid {
    display:grid;grid-template-columns:repeat(auto-fill,minmax(175px,1fr));gap:6px;
  }
  .ch-missing-item {
    display:flex;align-items:flex-start;gap:7px;
    background:var(--surface3);border:1px solid var(--border2);
    border-radius:8px;padding:8px 10px;
    animation:slideDown .3s ease both;
  }
  .ch-missing-dot { width:5px;height:5px;border-radius:50%;flex-shrink:0;margin-top:5px; }
  .ch-missing-field { font-size:.75rem;font-weight:600;color:var(--text2);line-height:1.3; }
  .ch-missing-tip   { font-size:.67rem;color:var(--muted);margin-top:1px; }

  /* ── Verdict banner ── */
  .ch-verdict {
    border-radius:var(--radius); padding:18px;
    display:flex;align-items:flex-start;gap:13px;
    border:1px solid transparent; animation:fadeUp .4s ease;
  }
  .ch-verdict-ico {
    width:44px;height:44px;border-radius:11px;flex-shrink:0;
    display:flex;align-items:center;justify-content:center;
    background:rgba(255,255,255,.06);
  }
  .ch-verdict-label {
    font-family:'DM Serif Display',serif;
    font-size:1.2rem;font-weight:400;margin-bottom:4px;
  }
  .ch-verdict-sub { font-size:.74rem;line-height:1.55;opacity:.72; }

  /* ── Confidence bars ── */
  .ch-conf-row { display:flex;align-items:center;gap:10px;margin-bottom:10px; }
  .ch-conf-row:last-child { margin-bottom:0; }
  .ch-conf-name { width:108px;font-size:.73rem;color:var(--muted);font-weight:500;flex-shrink:0; }
  .ch-conf-track { flex:1;height:5px;background:var(--surface2);border-radius:5px;overflow:hidden; }
  .ch-conf-fill  { height:100%;border-radius:5px;animation:barGrow .9s cubic-bezier(.34,1.56,.64,1) both; }
  .ch-conf-pct   { width:34px;text-align:right;font-size:.73rem;font-weight:700;font-variant-numeric:tabular-nums; }

  /* ── Reasons ── */
  .ch-reasons { display:flex;flex-direction:column;gap:7px; }
  .ch-reason {
    display:flex;gap:10px;align-items:flex-start;
    background:var(--surface2);border:1px solid var(--border2);
    border-radius:10px;padding:10px 12px;
    animation:fadeUp .35s ease both;transition:border-color .2s var(--ease);
  }
  .ch-reason:hover { border-color:#22c55e30; }
  .ch-reason-dot { width:5px;height:5px;border-radius:50%;background:var(--accent);flex-shrink:0;margin-top:7px;box-shadow:0 0 5px var(--accent); }
  .ch-reason-txt { font-size:.79rem;line-height:1.62;color:var(--text2); }

  /* ── Section label ── */
  .ch-section-lbl {
    display:flex;align-items:center;gap:9px;
    font-size:.6rem;font-weight:600;letter-spacing:.1em;
    text-transform:uppercase;color:var(--muted);
    animation:fadeUp .3s ease both;
  }
  .ch-section-lbl::before,.ch-section-lbl::after {
    content:'';flex:1;height:1px;background:var(--border);
  }

  /* ── Footer ── */
  .ch-footer {
    text-align:center;font-size:.67rem;color:var(--muted);
    line-height:1.65;padding-bottom:10px;
    animation:fadeUp .5s ease both;
  }

  /* ── Responsive ── */
  @media(min-width:540px){
    .ch-hero { padding:44px 24px 36px; }
    .ch-body { padding:22px 24px 70px; }
    .ch-card-hdr { padding:16px 20px 0; }
    .ch-card-body { padding:13px 20px 18px; }
    .ch-ta { font-size:.92rem; min-height:115px; }
    .ch-bar { padding:0 24px; }
  }
  @media(min-width:860px){
    .ch-hero { padding:56px 32px 46px; }
    .ch-body { padding:26px 0 80px; }
  }
  @media(max-width:380px){
    .ch-hero-h1 { font-size:1.42rem; }
    .ch-pills { grid-template-columns:repeat(2,1fr); }
    .ch-missing-grid { grid-template-columns:1fr; }
    .ch-bar-pill { display:none; }
  }
`;

function useCSS() {
  useEffect(() => {
    const id = 'ch-css';
    if (!document.getElementById(id)) {
      const el = document.createElement('style');
      el.id = id; el.textContent = CSS;
      document.head.appendChild(el);
    }
  }, []);
}

// ─── Sub-components ────────────────────────────────────────────────────────────

function TopBar() {
  return (
    <div className="ch-bar">
      <div className="ch-bar-logo"><Icon name="leaf" size={15} /></div>
      <div className="ch-bar-title">CinnamonHarvest</div>
      <div className="ch-bar-pill">AI · CCGI</div>
    </div>
  );
}

function Hero() {
  return (
    <div className="ch-hero">
      <div className="ch-hero-grid" />
      <div className="ch-hero-inner">
        <div className="ch-eyebrow">
          <div className="ch-eyebrow-dot" />
          Ceylon Cinnamon · CCGI Certified
        </div>
        <h1 className="ch-hero-h1">Harvest <em>Readiness</em><br />Checker</h1>
        <p className="ch-hero-sub">
          Describe a cinnamon shoot in plain language or speak your measurements.
          Provide as many details as possible for the most reliable result.
        </p>
      </div>
    </div>
  );
}

function InputCard({ text, setText, loading, recording, onMic, onAnalyse }) {
  return (
    <div className="ch-card">
      <div className="ch-card-hdr">
        <div className="ch-card-ico"><Icon name="sparkle" size={14} /></div>
        <div className="ch-card-lbl">Shoot Description</div>
      </div>
      <div className="ch-card-body">
        <div className="ch-ta-wrap">
          <textarea
            className="ch-ta"
            value={text}
            onChange={e => setText(e.target.value)}
            onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); onAnalyse(); } }}
            placeholder={'Describe the shoot, e.g.:\n"Height 155 cm, trunk 4.2 cm, age 20 months, brownish green leaves, rough and peeling dark brown bark, 18 leaves, very straight"'}
          />
          <button className={`ch-mic ${recording ? 'rec' : 'idle'}`} onClick={onMic}
            title={recording ? 'Stop recording' : 'Speak measurements'}>
            <Icon name={recording ? 'stop' : 'mic'} size={14} />
          </button>
        </div>
        <div className="ch-hint">
          <Icon name="info" size={11} />
          <span>More fields = higher confidence · Press Enter to analyse</span>
        </div>
        <button
          className={`ch-btn ${loading || !text.trim() ? 'off' : 'on'}`}
          disabled={loading || !text.trim()}
          onClick={onAnalyse}
        >
          {loading && <div className="ch-btn-shimmer" />}
          {loading
            ? <><div className="ch-spin" />Analysing shoot…</>
            : <><Icon name="search" size={16} />Check Harvest Readiness</>}
        </button>
      </div>
    </div>
  );
}

function DetectedFields({ fields }) {
  const entries = Object.entries(fields).filter(([, v]) => v !== null && v !== undefined);
  if (!entries.length) return null;
  return (
    <div className="ch-card" style={{ animationDelay: '0.05s' }}>
      <div className="ch-card-hdr">
        <div className="ch-card-ico"><Icon name="eye" size={14} /></div>
        <div className="ch-card-lbl">Detected Values</div>
      </div>
      <div className="ch-card-body">
        <div className="ch-pills">
          {entries.map(([k, val], i) => {
            const m = FIELD_META[k] || { label: k, unit: '', icon: 'info' };
            return (
              <div className="ch-pill" key={k} style={{ animationDelay: `${i * 0.04}s` }}>
                <div className="ch-pill-lbl">
                  <Icon name={m.icon} size={10} />{m.label}
                </div>
                <div className="ch-pill-val">{String(val)}{m.unit ? ` ${m.unit}` : ''}</div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

// ── Completeness / confidence warning card ─────────────────────────────────────
function CompletenessCard({ completeness }) {
  if (!completeness) return null;
  const { total_provided, total_fields, tier, missing_fields, is_reliable } = completeness;
  const tc = TIER_CONFIG[tier] || TIER_CONFIG.low;
  const pct = Math.round((total_provided / total_fields) * 100);

  return (
    <div className="ch-complete" style={{ background: tc.bg, borderColor: tc.border }}>
      {/* Header row */}
      <div className="ch-complete-top">
        <div className="ch-complete-left">
          <div className="ch-complete-icon" style={{ background: `${tc.color}18`, color: tc.color }}>
            <Icon name={is_reliable ? 'shield' : 'warn'} size={15} />
          </div>
          <div>
            <div className="ch-complete-tier" style={{ color: tc.color }}>{tc.label}</div>
            <div className="ch-complete-count">
              {total_provided} of {total_fields} fields provided
            </div>
          </div>
        </div>
        <div className="ch-complete-pct" style={{ color: tc.color }}>{pct}%</div>
      </div>

      {/* Progress bar */}
      <div className="ch-progress-track">
        <div
          className="ch-progress-fill"
          style={{ width: `${pct}%`, background: tc.color }}
        />
      </div>

      {/* Missing fields */}
      {missing_fields && missing_fields.length > 0 && (
        <>
          <div className="ch-missing-head">
            <Icon name="plus" size={11} />
            Add these fields to improve accuracy
          </div>
          <div className="ch-missing-grid">
            {missing_fields.map((f, i) => (
              <div className="ch-missing-item" key={f} style={{ animationDelay: `${i * 0.04}s` }}>
                <div className="ch-missing-dot" style={{ background: tc.color }} />
                <div>
                  <div className="ch-missing-field">{f}</div>
                  <div className="ch-missing-tip">{MISSING_FIELD_TIPS[f] || ''}</div>
                </div>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

const CONF_BARS = [
  { key: 'Ready',        color: '#4ade80' },
  { key: 'Nearly Ready', color: '#fbbf24' },
  { key: 'Not Ready',    color: '#60a5fa' },
];

function ResultSection({ result }) {
  const v = VERDICT[result.prediction] || VERDICT['Not Ready'];
  return (
    <>
      {/* Verdict */}
      <div className="ch-verdict"
        style={{ background: v.bg, borderColor: v.border, boxShadow: `0 4px 24px ${v.glow}18` }}>
        <div className="ch-verdict-ico" style={{ color: v.accent }}>
          <Icon name={v.icon} size={21} />
        </div>
        <div>
          <div className="ch-verdict-label" style={{ color: v.accent }}>{v.label}</div>
          <div className="ch-verdict-sub" style={{ color: v.accent }}>{v.sub}</div>
        </div>
      </div>

      {/* Confidence */}
      <div className="ch-card" style={{ animationDelay: '0.07s' }}>
        <div className="ch-card-hdr">
          <div className="ch-card-ico"><Icon name="chart" size={14} /></div>
          <div className="ch-card-lbl">Model Confidence</div>
        </div>
        <div className="ch-card-body">
          {CONF_BARS.map(({ key, color }) => (
            <div className="ch-conf-row" key={key}>
              <div className="ch-conf-name">{key}</div>
              <div className="ch-conf-track">
                <div className="ch-conf-fill"
                  style={{ width: `${result.confidence?.[key] ?? 0}%`, background: color }} />
              </div>
              <div className="ch-conf-pct" style={{ color }}>
                {Math.round(result.confidence?.[key] ?? 0)}%
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Reasons */}
      <div className="ch-card" style={{ animationDelay: '0.13s' }}>
        <div className="ch-card-hdr">
          <div className="ch-card-ico"><Icon name="info" size={14} /></div>
          <div className="ch-card-lbl">Analysis Details</div>
        </div>
        <div className="ch-card-body">
          <div className="ch-reasons">
            {result.reasons?.map((r, i) => (
              <div className="ch-reason" key={i} style={{ animationDelay: `${i * 0.06}s` }}>
                <div className="ch-reason-dot" />
                <div className="ch-reason-txt">{r}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </>
  );
}

// ─── Main ─────────────────────────────────────────────────────────────────────
export default function CinnamonHarvest() {
  useCSS();

  const [text, setText]           = useState('');
  const [loading, setLoading]     = useState(false);
  const [statusMsg, setMsg]       = useState('');
  const [error, setError]         = useState('');
  const [fields, setFields]       = useState(null);
  const [completeness, setComp]   = useState(null);
  const [result, setResult]       = useState(null);
  const [recording, setRec]       = useState(false);
  const recRef    = useRef(null);
  const resultRef = useRef(null);

  const toggleMic = useCallback(() => {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) { alert('Voice input not supported. Use Chrome or Edge.'); return; }
    if (recording) { recRef.current?.stop(); setRec(false); return; }
    const rec = new SR();
    rec.lang = 'en-US'; rec.interimResults = true; rec.continuous = true;
    recRef.current = rec;
    const base = text;
    rec.onresult = e => {
      let interim = '', final = base;
      for (const r of e.results) {
        if (r.isFinal) final += (final ? ' ' : '') + r[0].transcript;
        else interim = r[0].transcript;
      }
      setText(final + (interim ? ' ' + interim : ''));
    };
    rec.onerror = () => setRec(false);
    rec.onend   = () => setRec(false);
    rec.start(); setRec(true);
  }, [recording, text]);

  const analyse = useCallback(async () => {
    if (!text.trim() || loading) return;
    setLoading(true); setError(''); setResult(null); setFields(null); setComp(null);
    try {
      // Step 1: parse
      setMsg('Reading your description…');
      const pr = await fetch(`${API_BASE}/api/parse`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text }),
      });
      if (!pr.ok) throw new Error(`Parse error (${pr.status})`);
      const { fields: pf, completeness: pc } = await pr.json();
      setFields(pf);
      setComp(pc);

      // Step 2: predict
      setMsg('Running harvest readiness model…');
      const rr = await fetch(`${API_BASE}/api/predict`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ fields: pf, completeness: pc }),
      });
      if (!rr.ok) {
        const body = await rr.json();
        if (body.error === 'insufficient_data') {
          throw new Error(body.message || 'Not enough data to predict.');
        }
        throw new Error(`Predict error (${rr.status})`);
      }
      setResult(await rr.json());
      setMsg('');
      setTimeout(() => resultRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 120);
    } catch (e) {
      setError(e.message); setMsg('');
    } finally {
      setLoading(false);
    }
  }, [text, loading]);

  return (
    <div className="ch">
      <TopBar />
      <Hero />
      <div className="ch-body">

        <InputCard
          text={text} setText={setText}
          loading={loading} recording={recording}
          onMic={toggleMic} onAnalyse={analyse}
        />

        {loading && statusMsg && (
          <div className="ch-loading">
            <div className="ch-spin-green" />{statusMsg}
          </div>
        )}

        {error && (
          <div className="ch-err">
            <div className="ch-err-head"><Icon name="warn" size={14} />Error</div>
            <div className="ch-err-body">{error}</div>
            <div className="ch-err-tip">Make sure Flask backend is running at {API_BASE}</div>
          </div>
        )}

        {fields && <DetectedFields fields={fields} />}

        {/* Always show completeness after parsing — even before result */}
        {completeness && (
          <CompletenessCard completeness={completeness} />
        )}

        <div ref={resultRef}>
          {result && (
            <>
              <div className="ch-section-lbl" style={{ animationDelay: '0.04s' }}>Result</div>
              <ResultSection result={result} />
            </>
          )}
        </div>

        <div className="ch-footer">
          CinnamonHarvest AI · Ceylon Cinnamon Growers Institute data<br />
          For guidance only — confirm with a field agronomist before harvest.
        </div>
      </div>
    </div>
  );
}
